<script setup>import{onMounted,ref}from'vue';import{request}from'../api';const org='DEMO-CS',data=ref({tickets:[],activeCustomers:0,publishedArticles:0,openTickets:0,overdueTickets:0}),busy=ref(false),error=ref('');async function load(){try{data.value=await request('/api/service/dashboard?organizationCode='+org)}catch(e){error.value=e.message}}async function scenario(){busy.value=true;error.value='';try{const x=Date.now(),customer=await request('/api/service/customers',{method:'POST',body:JSON.stringify({organizationCode:org,customerCode:'CUST-'+x,name:'上海示范客户',level:'A',contactName:'王经理',contactPhone:'13800000000'})}),ticket=await request('/api/service/tickets',{method:'POST',body:JSON.stringify({organizationCode:org,ticketNo:'CS-'+x,customerId:customer.id,channel:'WECHAT',category:'技术支持',priority:'P2',subject:'客户端无法连接服务',description:'升级后出现连接超时',slaMinutes:240})});await request(`/api/service/tickets/${ticket.id}/assign`,{method:'POST',body:JSON.stringify({assignee:'技术支持一组'})});await request(`/api/service/tickets/${ticket.id}/messages`,{method:'POST',body:JSON.stringify({messageType:'PUBLIC',senderName:'客服专员',content:'已定位代理配置问题，正在处理'})});await request(`/api/service/tickets/${ticket.id}/resolve`,{method:'POST',body:JSON.stringify({resolution:'完成代理配置修复并验证连接'})});await load()}catch(e){error.value=e.message}finally{busy.value=false}}onMounted(load)</script>
<template><section class="dw-head"><div><span>CUSTOMER SERVICE</span><h3>客户服务与SLA指挥台</h3><p>覆盖受理、分派、客户沟通、解决、确认、重开和超时升级。</p></div><button @click="scenario" :disabled="busy">{{busy?'正在流转…':'创建服务闭环'}}</button></section><p v-if="error" class="err">{{error}}</p><section class="metrics"><article><span>活跃客户</span><b>{{data.activeCustomers}}</b></article><article><span>开放工单</span><b>{{data.openTickets}}</b></article><article><span>SLA逾期</span><b>{{data.overdueTickets}}</b></article><article><span>已发布知识</span><b>{{data.publishedArticles}}</b></article></section><section class="panel"><h4>服务工单队列</h4><table><tr><th>工单</th><th>渠道/分类</th><th>优先级</th><th>责任组</th><th>SLA到期</th><th>状态</th></tr><tr v-for="t in data.tickets" :key="t.id"><td><b>{{t.ticketNo}}</b><small>{{t.subject}}</small></td><td>{{t.channel}} / {{t.category}}</td><td>{{t.priority}}</td><td>{{t.assignee||'待分派'}}</td><td>{{t.dueAt?.replace('T',' ').slice(0,16)}}</td><td><i>{{t.status}}</i></td></tr></table></section></template>
<style scoped>.dw-head{display:flex;justify-content:space-between;align-items:end;background:#233f54;color:#fff;padding:26px 30px;border-radius:14px}.dw-head span{font-size:11px;letter-spacing:.16em;color:#9fc6df}.dw-head h3{font-size:25px;margin:7px 0}.dw-head p{margin:0;color:#ccdae4}.dw-head button{background:#70c5a8;border:0;border-radius:8px;padding:12px 18px;font-weight:700}.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin:18px 0}.metrics article,.panel{background:#fff;border:1px solid #dfe6e7;border-radius:12px;padding:20px}.metrics b{display:block;font-size:29px;margin-top:8px}.metrics span{color:#687980}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:12px;border-bottom:1px solid #edf0f1}td small{display:block;color:#718087}td i{font-style:normal;color:#1b715c}.err{color:#a43b35}@media(max-width:900px){.metrics{grid-template-columns:1fr 1fr}}</style>
